/// Saves [CliConfig] to `~/.fah/config.yaml`.
///
/// ... existing doc ...
///
/// gh-242 three-way merge: [base] is the config this process loaded at
/// boot (the REPL's `saved` snapshot, re-synced after sanctioned
/// settings-hub writes). With a baseline, only the top-level sections the
/// caller CHANGED vs [base] are rendered over the current disk state — a
/// section whose render is byte-identical to the baseline is dropped from
/// the emit and the on-disk block survives untouched, so a long-lived
/// REPL can never re-render its boot values over another process's
/// mid-session edits. Sections REMOVED by this process (present in the
/// baseline render, absent now) are deleted from the disk state; without
/// a baseline the save keeps the legacy caller-wins whole-render contract.
///
/// [projectDir] targets the project file: a changed project-capable
/// section (see [projectSaveSections]) that LIVES in
/// `<projectDir>/.fah/config.yaml` is written THERE (the project scope
/// wins at boot) instead of the global file — the global copy stays
/// byte-identical. [forceGlobal] (`--global`) disables the targeting and
/// forces the global file for every section.
Future<void> saveCliConfig(
 String homeDir,
 CliConfig config, {
 CliConfig? base,
 String? projectDir,
 bool forceGlobal = false,
}) async {
 final dir = Directory('$homeDir/.fah');
 if (!dir.existsSync()) dir.createSync(recursive: true);
 final file = File('${dir.path}/config.yaml');
 await _serializedConfigWrite(file.path, () async {
   final diskText = file.existsSync() ? file.readAsStringSync() : '';
   final merged = _mergeWithOnDisk(file, config, diskText);
   final (:emitted, :removed) = threeWayEmit(merged, base);
   final targeted = (projectDir == null || forceGlobal)
       ? const <String>{}
       : await saveChangedProjectSections(
           projectDir: projectDir,
           merged: merged,
           base: base,
